/*<info serverAlias="DBAFF-Affiliate_Athena000" executers="bodbDownlineNet" isFunction="0" isNested="0"></info>*/ALTER PROCEDURE [dbo].[Aff_User_GetDefaultProductCommission]     @Environment    VARCHAR(20) = 'Local Development'AS/**    * Created by    : Brian    * Date            : 20130709    * Task            : Get Default Group Commision    * DB            : DB052.Affiliate_Alpha    * Revisions    :        - 20140516@Bobby: Add default CommGroup setting		- 20220420@Malcolm: Get @GroupId = 101  [RedmineId: #171766]    *        * Parameters:    @GroupID: group id    *      */BEGIN    SET NOCOUNT ON    DECLARE @productTmp TABLE (ProductId INT);    DECLARE  @GroupID INT = 101    -- get group settings info    SELECT g.GroupID        ,g.ProductID        ,g.TierID        ,g.MinAmount        ,g.MaxAmount        ,g.MinQM        ,g.MaxQM        ,g.Commission    FROM GroupSetting g WITH (NOLOCK)    WHERE g.GroupID = @GroupID    -- get the list of product list    INSERT INTO @productTmp    SELECT DISTINCT (ProductID)    FROM GroupSetting    WHERE GroupID = @GroupID    SELECT p.ProductID        ,p.ProductName    FROM Product p WITH (NOLOCK)    WHERE p.ProductID IN (            SELECT *            FROM @productTmp            )END